(function(){
'use strict';
const C=window.CompanionCore,B=window.CompanionBackups,F=window.CompanionFeatures,W=window.CompanionWorkspace,N=window.CompanionNarration,$=id=>document.getElementById(id),main=$('main');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,loadError,view='home',detailId='',installPrompt=null,toastTimer,recording=null,recordPending=false,audioURLs=[],practiceUnit=0,deviceDraft=null,pendingTool='';
try{state=C.load(localStorage);}catch(e){loadError=e;state=C.fresh();}
const date=s=>new Date(s).toLocaleDateString(undefined,{month:'short',day:'numeric'});
const session=()=>state.sessions.find(s=>s.id===state.activeId);
const activity=s=>F.activity(s)||C.activities.find(a=>a.id===s.activity);
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6500);}
function change(fn,paint=true){if(loadError){toast('Saved data could not be read. Open App & updates to recover it.');return false;}const draft=JSON.parse(JSON.stringify(state));try{fn(draft);const s=draft.sessions.find(s=>s.id===draft.activeId);if(s)s.updatedAt=new Date().toISOString();C.save(localStorage,draft);state=draft;scheduleAutoBackup();if(paint)render();return true;}catch(e){toast('Not saved: '+e.message);return false;}}
function update(fn,paint=true){const before=session(),step=before&&before.stage+':'+before.practiceStep;const ok=change(d=>fn(d.sessions.find(s=>s.id===d.activeId)),paint),after=session();if(ok&&paint&&after&&step!==after.stage+':'+after.practiceStep){main.focus({preventScroll:true});window.scrollTo(0,0);}return ok;}
function navigate(next){if(recording||recordPending){toast('Stop and save the voice note first.');return;}N.stop();if(next==='session'&&pendingTool&&session()){next=pendingTool;pendingTool='';}if(location.hash==='#'+next)route();else location.hash=next;}
function heading(kicker,title,description='',read=true){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h2>${title}</h2>${description?`<p class="lead">${description}</p>`:''}</div>${read?'<button class="quiet" data-action="read" aria-label="Read this page aloud">◖)) Listen</button>':''}</div>`;}
function person(name,seat){return `<div class="person-label"><span class="avatar ${seat?'second':''}">${esc(name.slice(0,1).toUpperCase())}</span><h3>${esc(name)}</h3></div>`;}
function field(label,key,value,placeholder=''){return `<label>${label}<textarea data-field="${key}" maxlength="2000" placeholder="${esc(placeholder)}">${esc(value)}</textarea></label>`;}
const tableArt=`<div class="hero-art"><div class="zen-table-art"><img src="./icons/zen-reference-table-v1.webp" alt="The Zen Trainer pool table"><img class="shot-paths" src="./icons/companion-shot-paths.svg" alt="Trainer-calculated shot: the gold object ball goes to the bottom-right pocket. The mint cue-ball path rebounds from the top cushion. The red ball stays still."></div><div class="companion-avatars" aria-hidden="true"><span>A</span><span>B</span><span>C</span><span>D</span><span>+</span></div><div class="art-caption">TRAINER-CALCULATED SHOT<br><span class="cue-legend">Mint: cue ball</span> · <span class="object-legend">Gold: object ball</span></div></div>`;
function home(){const s=session(),last=state.sessions.find(s=>s.status==='completed');return `<div class="hero"><div><p class="eyebrow">A LITTLE PLAY. GOOD COMPANIONS.</p><h2>Get more from <br>your time at the table.</h2><p class="lead">Explore a shot. Test an idea. Help each other find something that sticks.</p><div class="actions"><button class="primary" data-nav="${s?'session':'new'}">${s?'Continue session':'New session'} <span aria-hidden="true">→</span></button>${s?'<button data-nav="new">New session</button>':''}<button class="quiet" data-action="read" aria-label="Listen to the introduction">◖)) Listen</button></div><p class="hint">Solo practice. Companions. Coaches. Groups.</p></div>${tableArt}</div><div class="section-top"><h3>A simple way forward</h3></div><div class="grid"><article class="card"><span class="card-number">1</span><h3>Notice together</h3><p>Start with a few shots or something that happened. Describe what you see before deciding what to work on.</p></article><article class="card"><span class="card-number">2</span><h3>Try one thing</h3><p>Choose a small question, compare ideas, then take turns trying it on your table.</p></article><article class="card"><span class="card-number">3</span><h3>Keep what helps</h3><p>One useful takeaway each. A good place to pick up when you meet again.</p></article></div>${last?`<div class="section-top"><h3>From your last session</h3></div><article class="card"><p class="eyebrow">${esc(C.names(state,last).join(' & '))} · ${date(last.updatedAt)}</p><h3>${esc(last.next||activity(last).title)}</h3><button data-nav="detail/${last.id}">Revisit the discoveries</button></article>`:''}`;}
function rosterRow(name,i){return `<div class="roster-row"><label>Player ${i+1}<input name="player" maxlength="60" autocomplete="off" value="${esc(name)}" placeholder="Name or nickname" required></label><label class="role-pick">Role<select name="role"><option value="player">Player</option><option value="coach">Coach</option></select></label><label class="group-pick" hidden>Group<select name="group"><option value="0">Group 1</option><option value="1">Group 2</option></select></label><button type="button" data-remove-player aria-label="Remove player ${i+1}">×</button></div>`;}
function newSession(){const last=state.sessions[0],names=last?C.names(state,last):['',''];return `${heading('NEW SESSION','Who’s at the table?','Practice on your own, with companions, or with a coach. Your other sessions stay saved.')}<form id="startForm"><fieldset><legend>How would you like to practice?</legend><div class="choices" data-choice="format"><button type="button" data-value="solo" aria-pressed="false">Solo practice</button><button type="button" data-value="coaching" aria-pressed="false">With a coach</button><button type="button" data-value="together" aria-pressed="true">One shared group</button><button type="button" data-value="partners" aria-pressed="false">Partner sets</button><button type="button" data-value="groups" aria-pressed="false">Two groups</button></div><p id="formatHint" class="hint">Everyone takes turns. Each person keeps their own observations and discoveries.</p></fieldset><div id="roster">${names.map(rosterRow).join('')}</div><button type="button" id="addPlayer">+ Add player</button><p class="hint">1–24 people. Coaches keep notes without taking player turns. Partner sets use adjacent names: 1 + 2, 3 + 4, and so on.</p><fieldset style="margin-top:24px"><legend>What sounds good today?</legend><div class="choices" data-choice="mood"><button type="button" data-value="relaxed" aria-pressed="false">Relaxed exploration</button><button type="button" data-value="focused" aria-pressed="true">Focused practice</button><button type="button" data-value="match" aria-pressed="false">Match preparation</button></div></fieldset><fieldset><legend>Roughly how much time?</legend><div class="choices" data-choice="minutes"><button type="button" data-value="30" aria-pressed="false">30 minutes</button><button type="button" data-value="60" aria-pressed="true">1 hour</button><button type="button" data-value="0" aria-pressed="false">Lots of free time</button></div></fieldset><p class="hint">Share a device, or send a session copy through Devices. Copies include everyone’s written notes and results; they do not update live. Use your keyboard microphone in any text field.</p><div class="wizard-actions"><button type="button" data-nav="home">Back</button><button class="primary" type="submit">Let’s begin →</button></div></form>`;}
function groupName(s,i){return C.units(s).length===1?'Everyone':C.units(s).every(u=>u.length===2)?'Partner set '+(i+1):'Group '+(i+1);}
function practiceScores(s,n,counts){if(s.work?.social)return `<p>Just-play mode · enjoy a rack with advice off.</p><button data-nav="workshop">Return to structured practice</button>`;const groups=C.units(s);practiceUnit=Math.min(practiceUnit,groups.length-1);const group=groups[practiceUnit],turn=C.seat(s,practiceUnit),attempts=F.practiceAttempts(s).filter(a=>group.includes(a.seat));return `${groups.length>1?`<label>Practicing now<select id="practiceGroup">${groups.map((g,i)=>`<option value="${i}" ${i===practiceUnit?'selected':''}>${groupName(s,i)} · ${g.map(j=>esc(n[j])).join(' & ')}</option>`).join('')}</select></label><p class="hint">Each set keeps its own turn and counts. Regroup to compare discoveries afterward.</p>`:''}<div class="score-grid">${group.map(i=>`<div class="score ${turn===i?'active':''}">${esc(n[i])}<strong>${counts[i].worked} <span>worked / ${counts[i].total} attempts</span></strong><span class="target-caption">${esc(s.work?.targets[i]?.criterion||activity(s).criterion)} · ${esc(s.work?.targets[i]?.level||'supported')}</span><span>${turn===i?'Your turn · '+(attempts.length%5+1)+' of 5':'Observe, then swap'}</span></div>`).join('')}</div><div class="actions results"><button class="primary" data-result="true">✓ Worked</button><button data-result="false">↻ Try again</button></div><div class="actions" style="margin-top:12px"><button class="quiet" data-action="undo" ${attempts.length?'':'disabled'}>Undo this group’s last result</button><span class="hint">A small sample, not a skill rating.</span></div>`;}

function activeSession(){const s=session();if(!s)return `<div class="empty"><h3>No session in progress</h3><button class="primary" data-nav="new">Start together</button></div>`;const n=C.names(state,s),a=activity(s),solo=n.length===1;let body='';
 if(s.stage===0)body=`${heading(solo?'YOUR PRACTICE':'MAKE ROOM FOR EVERYONE',solo?'Make this time useful.':'A good practice partner starts here.',solo?'Notice what happens, test one idea, and keep what helps.':'You can have different goals and still help each other.')}<div class="card"><ul class="agreement"><li><span>01</span> Ask before offering a correction.</li><li><span>02</span> Test an idea together. Anyone can revise it.</li><li><span>03</span> Describe what happened before explaining why.</li><li><span>04</span> Each person chooses something useful to take away.</li></ul><label class="check-label"><input id="agree" type="checkbox" ${s.agreed?'checked':''}>${solo?'I’m ready to practice this way.':'We’re all happy to practice this way.'}</label></div><p class="hint">Choose when advice is welcome. During a rack, wait until the turn or rack is over unless the shooter asks.</p>`;
 if(s.stage===1)body=`${heading('NOTICE BEFORE CHOOSING','What is happening in your game?','Play a few shots, or recall one recent situation. One honest observation each is enough.')}<div class="grid two">${n.map((name,i)=>`<article class="card">${person(name,i)}${field('What feels reliable, or what breaks down?',`baseline.${i}`,s.baseline[i],i?'Describe one thing you actually noticed.':'Example: I make the shot, but lose position.')}<p class="hint">Keep guesses separate from what you observed.</p></article>`).join('')}</div><p class="hint">You can talk this through and continue without typing. Keep a voice note if you want to remember it.</p>`;
 if(s.stage===2)body=`${heading('ONE QUESTION TO EXPLORE','Choose what helps today.','Choose together after looking at your starting point.')}<div class="grid activities">${C.activities.map(item=>`<button class="card activity-choice" data-activity="${item.id}" aria-pressed="${s.activity===item.id}"><span class="eyebrow">${item.tag}</span><strong>${item.title}</strong><span class="muted">${item.description}</span></button>`).join('')}</div><div class="section-top"><h3>Something useful for each of you</h3><span>Optional · say it or save it</span></div><div class="grid two">${n.map((name,i)=>`<div>${field(esc(name)+' wants to take away…',`gains.${i}`,s.gains[i],i?'A better explanation, an observation, a new idea…':'A useful result, a little more confidence…')}</div>`).join('')}</div>`;
 if(s.stage===3){const step=a.steps[s.practiceStep],counts=C.counts(s),seat=C.seat(s);body=`${heading('TRY · '+a.title,esc(a.question),'One action at a time. Your time estimate is a guide, not a countdown.')}<div class="mini-steps">${a.steps.map((step,i)=>`<button data-practice="${i}" ${s.practiceStep===i?'aria-current="step"':''}>${i+1}. ${['Predict','Compare','Try','Use it'][i]}</button>`).join('')}</div><article class="card practice-card"><p class="eyebrow">STEP ${s.practiceStep+1} OF 4</p><h3>${step[0]}</h3><p>${step[1]}</p>${s.practiceStep===1?`<div class="criterion"><strong>Useful Trainer tools</strong><br>${a.tools}</div><button class="button quiet" data-work="trainer">Open this setup in Trainer ↗</button><p class="hint">Load the setup when ready, then return here with your changed layout.</p>`:''}${s.practiceStep===2?`<div class="criterion"><strong>Agree what counts:</strong> ${a.criterion}</div>${practiceScores(s,n,counts)}`:''}<div class="actions" style="margin-top:22px"><button class="primary" data-action="practice-next">${s.practiceStep===3?'Keep our discoveries →':'Next part →'}</button>${s.practiceStep===3?'<span class="hint">Advice off during turns. Reflect together afterward.</span>':''}</div></article>`;}
 if(s.stage===4)body=`${heading('KEEP SOMETHING USEFUL','What will you take with you?','Different takeaways are welcome. A short phrase or voice note is enough.')}<div class="grid two">${n.map((name,i)=>`<article class="card">${person(name,i)}${field('My useful discovery',`takeaways.${i}`,s.takeaways[i],'What helped, and when would I use it?')}<p class="small">Was this worth doing?</p><div class="choices" data-enjoyment="${i}">${[['yes','Yes'],['mixed','Mixed'],['change','Change it']].map(([v,l])=>`<button data-value="${v}" aria-pressed="${s.enjoyment[i]===v}">${l}</button>`).join('')}</div></article>`).join('')}</div><div style="margin-top:22px">${field('When we meet again…','next',s.next,'Try a related shot, use less guidance, or just play.')}</div><p class="hint">Learning, enjoyment and partner fit can be different. Everyone can give a different answer.</p>`;
 return `<div class="session-head"><div><strong>${n.map(esc).join(' & ')}</strong><br>${{relaxed:'Relaxed exploration',focused:'Focused practice',match:'Match preparation'}[s.mood]} · ${C.duration(s.minutes)} <span class="saved-stamp"> · saved locally</span></div><div class="session-tools"><button data-nav="sessions">Our sessions</button><button data-nav="new">New session</button><button data-nav="workshop">Practice tools</button><button data-nav="guide">Guide & voice</button><button data-nav="devices">Devices</button><button data-action="voice" id="tool-voice">● Voice note</button><button data-action="pause">Pause & leave</button></div></div><nav class="steps" aria-label="Session steps">${['Meet','Notice','Choose','Try','Keep'].map((label,i)=>`<button data-stage="${i}" ${s.stage===i?'aria-current="step"':''} ${i>s.stage?'disabled':''}><span class="step-no">${i+1}</span>${label}</button>`).join('')}</nav>${participants(s,n)}${body}<div class="wizard-actions"><button data-action="previous" ${s.stage===0?'disabled':''}>← Back</button>${s.stage!==3?`<button class="primary" data-action="next" ${s.stage===0&&!s.agreed?'disabled':''}>${s.stage===4?'Save & finish':'Continue →'}</button>`:''}</div><div id="voiceNotes" class="voice-list"></div>`;
}
function history(){
 const current=session();
 const sessions=current?[current,...state.sessions.filter(s=>s.id!==current.id)]:state.sessions;
 return heading('OUR SESSIONS','A place to pick up again.','Keep separate sessions for different companions, coaches and your own practice.')+'<div class="actions"><button class="primary" data-nav="new">New session</button></div>'+
  (sessions.length?`<div class="history-list">${sessions.map(s=>`
   <article class="${s.id===state.activeId?'strip':'card history-head'}">
    <div>
     <p class="eyebrow">${date(s.updatedAt)} · ${s.status==='active'?(s.id===state.activeId?'In progress':'Paused'):'Completed'}</p>
     <h3>${C.names(state,s).map(esc).join(' & ')}${s.id===state.activeId?' · your session is saved':''}</h3>
     <p>${esc(activity(s).title)} · ${C.names(state,s).length===1?'Solo practice':C.roles(s).includes('coach')?'With a coach':'Companion practice'}</p>
    </div>
    <div class="actions">
     <button ${s.status==='active'?`class="primary" data-action="resume" data-session="${s.id}"`:`data-nav="detail/${s.id}"`}>${s.status==='active'?'Continue session →':'View'}</button>
     <button class="quiet" data-action="delete-session" data-session="${s.id}" aria-label="Delete session with ${esc(C.names(state,s).join(' & '))}">Delete session</button>
    </div>
   </article>`).join('')}</div>`:
   '<div class="empty"><h3>Your first session starts here.</h3><p>Nothing to fill in before you begin.</p><button class="primary" data-nav="new">Start with friends</button></div>');
}
function discoveries(){const list=state.sessions.filter(s=>s.status==='completed');return heading('DISCOVERIES','Keep the useful bits.','Small discoveries, linked to the people and situations that helped you find them.')+(list.length?`<div class="history-list">${list.map(s=>`<article class="card"><p class="eyebrow">${date(s.updatedAt)} · ${esc(activity(s).title)}</p>${s.takeaways.map((t,i)=>`<div class="note-row"><strong>${esc(C.names(state,s)[i])}</strong><p>${esc(t||'No written takeaway. Revisit the session for any voice notes.')}</p></div>`).join('')}<button data-nav="detail/${s.id}">Open session${s.voice.length?' · '+s.voice.length+' voice notes':''}</button></article>`).join('')}</div>`:'<div class="empty"><h3>Something worth remembering.</h3><p>Finish a session to collect your discoveries here.</p></div>');}
function detail(){const s=state.sessions.find(s=>s.id===detailId);if(!s)return '<div class="empty">Session not found. <button data-nav="sessions">Our sessions</button></div>';const n=C.names(state,s);return `${heading('SESSION · '+date(s.updatedAt),n.map(esc).join(' & '),esc(activity(s).title))}<div class="grid two">${n.map((name,i)=>`<article class="card">${person(name,i)}<p class="eyebrow">Starting observation</p><p>${esc(s.baseline[i]||'Discussed at the table.')}</p><p class="eyebrow">Wanted to learn</p><p>${esc(s.gains[i]||'Explored together.')}</p><p class="eyebrow">Useful discovery</p><p>${esc(s.takeaways[i]||'No written takeaway.')}</p><p>Worth doing: <strong>${{yes:'Yes',mixed:'Mixed',change:'Change it','':'Not recorded'}[s.enjoyment[i]]}</strong></p></article>`).join('')}</div><article class="card" style="margin-top:18px"><h3>Our next time</h3><p>${esc(s.next||'Decide together when you meet.')}</p><p>${C.counts(s).map((c,i)=>`${esc(n[i])}: ${c.worked} worked in ${c.total} attempts`).join(' · ')}</p></article><div id="voiceNotes" class="voice-list"></div><div class="wizard-actions"><button data-nav="sessions">← Our sessions</button><button data-action="resume" data-session="${s.id}">Continue this session</button><button class="primary" data-action="again">Start another session with these people</button></div>`;}
function features(){return `${heading('TOOLKIT','Find your next good idea.','A little help for every part of your time at the table. Choose a tool and make it your own.',false)}<div class="toolkit-groups">${C.features.map(([title,rows,intro])=>{const tools=rows.filter(row=>['ready','device'].includes(row[1])&&row[3]);return tools.length?`<section class="toolkit-group"><h3>${esc(title)}</h3><p class="toolkit-intro">${esc(intro)}</p><div class="toolkit-list">${tools.map(([name,,description,path])=>`<article class="toolkit-item"><a href="#${esc(path)}">${esc(name)}<span aria-hidden="true">→</span></a><p>${esc(description)}</p></article>`).join('')}</div></section>`:'';}).join('')}</div>`;}

function devices(){return `${heading('DEVICES','Practice together. Bring your own device.','Share a session copy with friends.')}<div class="grid two"><article class="card"><h3>Send a session</h3><p>Choose a session and share its file using your device’s normal sharing tools. Written notes, names and attempt results are included for everyone. Private practice tools, preferences, media and audio travel only in a full backup.</p><label>Session<select id="copySession">${state.sessions.map(s=>`<option value="${s.id}" ${s.id===state.activeId?'selected':''}>${esc(C.names(state,s).join(', '))} · ${date(s.createdAt)}</option>`).join('')}</select></label><button class="primary" data-action="send-session" ${state.sessions.length?'':'disabled'}>Share session copy</button></article><article class="card"><h3>Bring contributions together</h3><p>Open a received copy, contribute your observations and discoveries, then send a copy back. Importing combines changes with the original session.</p><button data-action="receive-session">Open session copy</button><input id="sessionCopyFile" type="file" accept="application/json,.json" hidden><div id="sessionImportPreview" hidden></div></article></div><article class="card" style="margin-top:20px"><h3>One shared question, many perspectives</h3><p>Choose the activity and groups before sending copies. Each device can record a different partner set’s attempts and individual notes. If two devices change the same note differently, import stops and preserves both copies for you to resolve.</p><p class="hint">This is file sharing, not live synchronization. A group’s turns can differ between copies until you import them. Keep one device responsible for each set’s attempt counts. Share the merged copy again before the next round. Live joining and automatic synchronization require a connected service. Private feedback is kept locally and included in full backups.</p></article>`;}
function participants(s,n){return `<details class="participants card"><summary>People in this session · ${n.length}</summary><p>${n.map((name,i)=>esc(name)+(C.roles(s)[i]==='coach'?' (Coach)':'')).join(' · ')}</p><form id="addPersonForm"><div class="participant-fields"><label>Name or nickname<input name="name" maxlength="60" required></label><label>Role<select name="role"><option value="player">Player</option><option value="coach">Coach</option></select></label><label ${C.units(s).length===1?'hidden':''}>Join group<select name="unit">${C.units(s).map((g,i)=>`<option value="${i}">${groupName(s,i)}</option>`).join('')}</select></label></div><button type="submit" ${n.length>=24?'disabled':''}>Add to this session</button></form><p class="hint">Existing notes, results and recordings stay with their original person. If you shared a session file, finish combining those copies before adding someone.</p></details>`;}
function refreshRoster(){const rows=[...$('roster').children],format=$('startForm').querySelector('[data-choice=format] [aria-pressed=true]').dataset.value;rows.forEach((row,i)=>{row.querySelector('label').firstChild.textContent='Person '+(i+1);row.querySelector('[data-remove-player]').disabled=rows.length<=1;row.querySelector('[data-remove-player]').setAttribute('aria-label','Remove person '+(i+1));row.querySelector('.group-pick').hidden=format!=='groups';row.querySelector('.role-pick').hidden=format==='solo';});$('addPlayer').disabled=rows.length>=24||format==='solo';$('formatHint').textContent={solo:'Your observations, attempts and discoveries, ready to continue later.',coaching:'Players take the shots. Coaches can record observations, discoveries and voice notes.',together:'Everyone takes turns. Each person keeps their own observations and discoveries.',partners:'Each adjacent pair practices independently. Come back together to compare what helped.',groups:'Assign people to either group. Each group keeps its own turns, then everyone compares discoveries.'}[format];}
async function sendSessionCopy(){try{const id=$('copySession').value;let payload;if(!change(d=>{payload=C.packet(d,id);},false))return;const body=JSON.stringify(payload),name='Companion-Session-'+new Date().toISOString().slice(0,10)+'.billiards.json';const file=new File([body],name,{type:'application/json'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Companion Play session'});return;}if(window.BilliardsAndroid?.saveTrainerExport){const saved=window.BilliardsAndroid.saveTrainerExport(name,body);if(!saved)throw Error('Could not save the session copy.');toast('Session saved: '+saved+'. Share this file with your companions.');}else{const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Session file prepared. Send it using your usual sharing app.');}}catch(e){if(e.name!=='AbortError')toast('Not shared: '+e.message);}}
async function readSessionCopy(e){const file=e.target.files[0];e.target.value='';deviceDraft=null;if(!file)return;try{if(file.size>10000000)throw Error('Session copies must be smaller than 10 MB.');const input=JSON.parse(await file.text());C.receive(state,input);deviceDraft=input;const area=$('sessionImportPreview');area.hidden=false;area.innerHTML=`<p class="hint">${esc(input.people.map(p=>p.name).join(', '))}<br>${esc(C.activities.find(a=>a.id===input.session.activity).title)} · ${input.session.attempts.length} results<br>Review the sender before importing. Existing unrelated sessions stay in place.</p><button class="primary" data-action="apply-session">Import this session copy</button>`;}catch(e){toast('Not imported: '+e.message);}}
function settings(){const native=!!(window.BilliardsBundledAndroid||window.BilliardsBundledWindows);return `${heading('APP & UPDATES','Keep it simple. Keep it yours.','',false)}<div class="grid two"><article class="card" id="tool-updates"><p class="eyebrow">INSTALL ONCE</p><h3>Updates inside the app</h3><p>${native?'You’re inside the installed Billiards Trainer. This workspace uses its existing content updater.':'Open this workspace in your installed Billiards Trainer, or install it from Chrome / Edge when offered.'} Saved sessions stay on this device when the content updates.</p><div class="actions"><button class="primary" data-action="updates">Check for updates</button><button data-action="install" ${native?'hidden':''}>Install options</button></div><p class="hint">Restart when an update is ready. No ZIP files or repeated extraction.</p></article><article class="card"><p class="eyebrow">YOUR DEVICE</p><h3>Voice & storage</h3><p>Fixed guidance uses Chase recordings at 1.2×. Personal text uses your device voice. Pause, resume, and stop sit beside each Listen button.</p><div class="actions"><button data-action="storage">Request persistent storage</button></div><p id="storageStatus" class="hint">${state.sessions.length} sessions saved locally. Clearing app data removes them; export a backup to keep a separate copy.</p></article></div><article class="card" id="tool-backup" style="margin-top:20px"><p class="eyebrow">COMPANION BACKUP</p><h3>Keep a complete copy of your practice</h3><p>Export just this workspace. Restore replaces companion records only; it does not change your games or Trainer settings.</p>${autoBackupControls()}<div class="actions"><button data-action="export">Prepare backup</button><button data-action="import">Choose backup to restore</button><input id="backupFile" type="file" accept="application/json,.json" hidden></div><div id="backupArea" hidden><textarea id="backupText" class="backup-text" aria-label="Companion backup JSON" readonly></textarea><div class="actions"><button data-action="download">Save backup file</button><button data-action="copy">Copy backup</button></div></div><p class="hint" id="backupStatus"></p></article>${loadError?'<div class="warning"><strong>Saved data needs attention.</strong><p>The unreadable copy has not been changed.</p><button data-action="recover">Recover previous saved copy</button></div>':''}`;}
function render(){N.stop();W.cleanup();audioURLs.forEach(URL.revokeObjectURL);audioURLs=[];document.querySelectorAll('[data-view]').forEach(b=>{if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});main.innerHTML=(loadError&&view!=='settings'?'<div class="warning">Saved companion data could not be read. It has not been changed. <button data-nav="settings">Open recovery options</button></div>':'')+({home,new:newSession,session:activeSession,sessions:history,discoveries,detail,features,devices,settings}[view]||(()=>W.render(view)||home()))();if(session()?.work?.pressure.enabled)main.insertAdjacentHTML('afterbegin',W.pressureBanner());bind();W.bind(view);N.refresh();if(view==='settings')refreshAutoBackups();const s=view==='session'?session():view==='detail'?state.sessions.find(s=>s.id===detailId):null;if(s)renderVoice(s);}
function speak(trigger){const s=session();let id=view;if(view==='session'&&s)id=s.stage===3?(s.work?.drill?'drill-'+s.work.drill:'activity-'+s.activity)+'-'+s.practiceStep:['meet','notice','choose','','keep'][s.stage];N.listen([id],main.querySelector('h2')?.textContent||'Companion Play',trigger);}
function bind(){
 const form=$('startForm');if(form)form.onsubmit=e=>{e.preventDefault();const data=new FormData(form),mood=form.querySelector('[data-choice=mood] [aria-pressed=true]').dataset.value,minutes=Number(form.querySelector('[data-choice=minutes] [aria-pressed=true]').dataset.value);if(change(d=>C.start(d,data.getAll('player'),{mood,minutes,format:['solo','coaching'].includes(form.querySelector('[data-choice=format] [aria-pressed=true]').dataset.value)?'together':form.querySelector('[data-choice=format] [aria-pressed=true]').dataset.value,assignments:data.getAll('group').map(Number),roles:data.getAll('role')}),false))navigate('session');};
 document.querySelectorAll('[data-choice] button').forEach(b=>b.onclick=()=>{b.parentElement.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));if(b.parentElement.dataset.choice==='format'){if(b.dataset.value==='solo'){while($('roster').children.length>1)$('roster').lastElementChild.remove();$('roster').querySelector('[name=role]').value='player';}if(b.dataset.value==='coaching'){if($('roster').children.length===1)$('roster').insertAdjacentHTML('beforeend',rosterRow('',1));$('roster').children[0].querySelector('[name=role]').value='player';$('roster').children[1].querySelector('[name=role]').value='coach';}refreshRoster();}});
 if(form){$('addPlayer').onclick=()=>{const count=$('roster').children.length;if(count>=24)return;$('roster').insertAdjacentHTML('beforeend',rosterRow('',count));refreshRoster();$('roster').lastElementChild.querySelector('input').focus();};$('roster').onclick=e=>{const button=e.target.closest('[data-remove-player]');if(button&&$('roster').children.length>1){button.closest('.roster-row').remove();refreshRoster();}};refreshRoster();}
 if($('addPersonForm'))$('addPersonForm').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);if(change(d=>C.addParticipant(d,d.activeId,data.get('name'),{role:data.get('role'),unit:Number(data.get('unit'))})))toast('Person added. Existing notes and results are preserved.');};
 if($('practiceGroup'))$('practiceGroup').onchange=e=>{practiceUnit=Number(e.target.value);render();};
 if($('sessionCopyFile'))$('sessionCopyFile').onchange=readSessionCopy;
 main.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{const [field,index]=el.dataset.field.split('.');if(!['baseline','gains','takeaways','next'].includes(field))return;update(s=>{if(index===undefined)s[field]=el.value;else s[field][Number(index)]=el.value;},false);});
 if($('agree'))$('agree').onchange=e=>update(s=>s.agreed=e.target.checked);
 main.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>{const s=session();if(s.activity===b.dataset.activity&&!s.work?.drill)return;if(s.attempts.length&&!confirm('Change activity and start a fresh result set? Earlier results and notes stay saved.'))return;update(s=>{s.activity=b.dataset.activity;s.practiceStep=0;const q=F.ensure(s);q.drill='';q.round=C.uid();q.targets=q.targets.map(t=>({...t,criterion:''}));q.pressure.enabled=false;});});
 main.querySelectorAll('[data-enjoyment] button').forEach(b=>b.onclick=()=>update(s=>s.enjoyment[Number(b.parentElement.dataset.enjoyment)]=b.dataset.value));
 main.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>update(s=>s.stage=Number(b.dataset.stage)));
 main.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>update(s=>s.practiceStep=Number(b.dataset.practice)));
 main.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>update(s=>C.attempt(s,b.dataset.result==='true',practiceUnit)));
 if($('backupFile'))$('backupFile').onchange=restoreFile;
}
document.addEventListener('click',async e=>{
 const button=e.target.closest('button,[data-nav]');if(!button)return;
 if(button.dataset.nav){navigate(button.dataset.nav);return;}if(button.dataset.view){navigate(button.dataset.view);return;}
 const action=button.dataset.action;if(!action)return;
 if(action==='read'){speak(button);return;}
 if(action==='toggle-auto'){await toggleAutoBackup();return;}
 if(action==='restore-auto'){await restoreAutoBackup(button);return;}
 if(action==='delete-session'){
  if(recording||recordPending){toast('Stop and save the voice note first.');return;}
  const id=button.dataset.session,target=state.sessions.find(s=>s.id===id);
  if(!target){toast('Session not found.');return;}
  if(!confirm('Delete the session with '+C.names(state,target).join(' & ')+'? Its notes and results will be removed from Our sessions on this device.'))return;
  if(autoEnabled&&!loadError){try{await captureAutoBackup(true);}catch(e){toast('Session kept: '+e.message);return;}}
  // The existing previous-save recovery keeps the session and its audio together.
  if(change(d=>{
   d.sessions=d.sessions.filter(s=>s.id!==id);
   if(d.activeId===id)d.activeId=null;
  }))toast('Session deleted.');
  return;
 }
 if(action==='resume'){if(recording||recordPending){toast('Stop and save the voice note first.');return;}if(change(d=>C.resume(d,button.dataset.session),false)){practiceUnit=0;navigate('session');}return;}
 if(action==='pause'){if(recording||recordPending){toast('Stop and save the voice note first.');return;}if(change(d=>{const current=d.sessions.find(x=>x.id===d.activeId);if(current?.work)current.work.pressure.enabled=false;d.activeId=null;},false))navigate('sessions');return;}
 if(action==='send-session'){await sendSessionCopy();return;}
 if(action==='receive-session'){$('sessionCopyFile').click();return;}
 if(action==='apply-session'){if(!deviceDraft)return;try{const draft=C.receive(state,deviceDraft);if(change(d=>Object.assign(d,draft),false)){deviceDraft=null;toast('Session copy imported. Other sessions and local audio are unchanged.');navigate('sessions');}}catch(e){toast('Not imported: '+e.message);}return;}
 if(action==='previous'){update(s=>s.stage=Math.max(0,s.stage-1));return;}
 if(action==='next'){if(pendingTool&&session()?.agreed){navigate('session');return;}if(session()?.stage===4){if(change(d=>C.finish(d,d.sessions.find(s=>s.id===d.activeId)),false)){toast('Session saved. Your discoveries are ready to revisit.');navigate('discoveries');}}else update(s=>{if(s.stage===0&&!s.agreed)throw Error('Agree together before continuing.');s.stage++;});return;}
 if(action==='practice-next'){update(s=>{if(s.practiceStep<3)s.practiceStep++;else s.stage=4;});return;}
 if(action==='undo'){update(s=>{const group=C.units(s)[practiceUnit];const i=s.attempts.map(a=>group.includes(a.seat)&&F.practiceAttempts(s).includes(a)).lastIndexOf(true);if(i>=0)s.attempts.splice(i,1);});return;}
 if(action==='again'){const s=state.sessions.find(s=>s.id===detailId),names=C.names(state,s);if(change(d=>{const next=C.start(d,names,{mood:s.mood,minutes:s.minutes,roles:C.roles(s)});next.units=(s.units||[names.map((_,i)=>i)]).map(u=>u.slice());},false))navigate('session');return;}
 if(action==='voice'){W.stopVoice();const s=session();if(!s)return;const n=C.names(state,s);$('notePerson').innerHTML=n.map((v,i)=>`<option value="${i}">${esc(v)}</option>`).join('');$('recordStatus').textContent='Ready when you are.';$('noteDialog').showModal();return;}
 if(action==='updates'){if(window.BilliardsAppUpdates?.supported)window.BilliardsAppUpdates.check();else toast('Updates are unavailable in this preview. Open the installed Trainer or the live HTTPS app.');return;}
 if(action==='install'){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;}else toast('In Chrome or Edge, use the browser menu → Install app / Add to Home screen. In the installed Trainer, open Play → Play Together.');return;}
 if(action==='storage'){try{const persisted=await navigator.storage?.persist?.();$('storageStatus').textContent=persisted?'Persistent storage granted on this device. Keep a backup as well.':'Persistent storage was not granted. Sessions still save locally; keep an exported backup.';}catch(e){toast(e.message);}return;}
 if(action==='export'){button.disabled=true;try{await exportBackup();}catch(e){toast('Backup failed: '+e.message);}finally{button.disabled=false;}return;}
 if(action==='import'){$('backupFile').click();return;}
 if(action==='download'){const text=$('backupText')?.value;if(!text)return;if(window.BilliardsAndroid?.saveTrainerExport){const name='Play-Together-Backup-'+new Date().toISOString().slice(0,10)+'.billiards.json';const saved=window.BilliardsAndroid.saveTrainerExport(name,text);toast(saved?'Backup saved: '+saved:'Backup could not be saved. Use Copy backup to preserve the text.');}else{const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='Play-Together-Backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}return;}
 if(action==='copy'){try{await navigator.clipboard.writeText($('backupText').value);toast('Backup copied.');}catch{$('backupText').focus();$('backupText').select();toast('Use Copy on the selected text.');}return;}
 if(action==='recover'){try{const raw=localStorage.getItem(C.KEY+'.previous');if(!raw)throw Error('No previous copy is available. Restore an exported backup.');const previous=C.validate(JSON.parse(raw));previous.revision=Math.max(previous.revision,state.revision)+1;localStorage.setItem(C.KEY,JSON.stringify(previous));state=previous;loadError=null;toast('Previous saved copy restored.');scheduleAutoBackup();render();}catch(e){toast(e.message);}return;}
});
function openAudio(){return new Promise((resolve,reject)=>{const request=indexedDB.open('billiards-play-together-audio',1);request.onupgradeneeded=()=>request.result.createObjectStore('notes',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function audioTask(mode,work){const db=await openAudio();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('notes',mode),store=tx.objectStore('notes');let result;const req=work(store);if(req)req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Audio save was interrupted.'));});}finally{db.close();}}
async function renderVoice(s){if(!s.voice.length||!$('voiceNotes'))return;const container=$('voiceNotes');container.innerHTML='<h3>Voice notes</h3>';for(const meta of s.voice){try{const record=await audioTask('readonly',store=>store.get(meta.id));if(!container.isConnected)return;const div=document.createElement('div');div.className='note-row';const p=document.createElement('p');p.textContent=C.names(state,s)[meta.seat]+' · '+Math.round(meta.seconds)+' seconds · '+date(meta.createdAt);div.append(p);if(record?.blob){const audio=document.createElement('audio');audio.controls=true;audio.preload='none';const url=URL.createObjectURL(record.blob);audioURLs.push(url);audio.src=url;div.append(audio);}else{const warning=document.createElement('p');warning.textContent='Audio file is unavailable. Restore a companion backup containing this note.';div.append(warning);}container.append(div);}catch{if(container.isConnected)container.append(document.createTextNode('Audio storage is unavailable.'));break;}}}
function closeNote(){if(recording||recordPending){toast('Stop and save your recording first.');return;}$('noteDialog').close();}
$('closeNote').onclick=closeNote;$('noteDialog').addEventListener('cancel',e=>{if(recording||recordPending){e.preventDefault();toast('Stop and save your recording first.');}});
$('record').onclick=async()=>{
 if(recording||recordPending)return;
 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){$('recordStatus').textContent='Recording is unavailable in this browser or shell. Use the keyboard microphone in a note field.';return;}
 const s=session();if(!s)return;const sessionId=s.id,seat=Number($('notePerson').value);recordPending=true;$('record').disabled=true;$('recordStatus').textContent='Waiting for microphone permission…';let stream;
 try{N.stop();stream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(t=>MediaRecorder.isTypeSupported(t));const recorder=new MediaRecorder(stream,mime?{mimeType:mime}:{}),chunks=[],started=Date.now();recording=recorder;recordPending=false;$('stopRecord').disabled=false;$('notePerson').disabled=true;$('recordStatus').classList.add('recording');
 const timer=setInterval(()=>{$('recordStatus').textContent='Recording · '+Math.floor((Date.now()-started)/1000)+' seconds';},500);const limit=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},120000);
 recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};
 recorder.onerror=()=>{$('recordStatus').textContent='Recording failed. Please try again.';if(recorder.state==='recording')recorder.stop();};
 recorder.onstop=async()=>{clearInterval(timer);clearTimeout(limit);stream.getTracks().forEach(t=>t.stop());recording=null;recordPending=true;$('stopRecord').disabled=true;const blob=new Blob(chunks,{type:recorder.mimeType||mime||'audio/webm'}),meta={id:C.uid(),seat,createdAt:new Date().toISOString(),seconds:Math.min(120,(Date.now()-started)/1000)};try{if(!blob.size)throw Error('No audio was captured.');if(blob.size>15000000)throw Error('That audio note is too large. Try a shorter note.');await audioTask('readwrite',store=>store.put({id:meta.id,sessionId,blob}));if(!change(d=>{const target=d.sessions.find(s=>s.id===sessionId);if(!target)throw Error('Session not found.');target.voice.push(meta);},false))throw Error('Session note could not be linked.');$('recordStatus').textContent='Voice note saved on this device.';toast('Voice note saved.');render();}catch(e){$('recordStatus').textContent='Not saved: '+e.message;}finally{recordPending=false;$('record').disabled=false;$('notePerson').disabled=false;$('recordStatus').classList.remove('recording');}};
 recorder.start();$('recordStatus').textContent='Recording · speak naturally.';
 }catch(e){stream?.getTracks().forEach(t=>t.stop());recording=null;recordPending=false;$('record').disabled=false;$('recordStatus').textContent=e.name==='NotAllowedError'?'Microphone access was not allowed. You can still dictate with your keyboard microphone.':'Microphone could not start: '+e.message;}
};
$('stopRecord').onclick=()=>{if(recording?.state==='recording'){recording.stop();$('stopRecord').disabled=true;$('recordStatus').textContent='Saving your note…';}};
const blobData=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});
async function makeBackup(){return B.build(state,C,id=>audioTask('readonly',store=>store.get(id)),blobData);}
async function exportBackup(){const payload=await makeBackup();$('backupText').value=JSON.stringify(payload);$('backupArea').hidden=false;$('backupStatus').textContent=payload.state.sessions.length+' sessions and '+payload.audio.length+' audio notes and '+(payload.media||[]).length+' attachments ready. Save a copy outside the app.';}
async function restorePayload(payload){
 if(recording||recordPending)throw Error('Stop and save the voice note before restoring.');
 const checked=B.validate(payload,C);
 if(!confirm('Restore '+checked.state.sessions.length+' Companion sessions and '+checked.audio.length+' audio notes and '+checked.media.length+' attachments? This replaces Companion data on this device. Other Trainer data stays unchanged.'))return false;
 const before=localStorage.getItem(C.KEY);
 if(autoEnabled&&!loadError)await captureAutoBackup(true);
 // Stage audio with new IDs; failed restore cannot overwrite existing recordings.
 const mapped=new Map();for(const row of [...checked.audio,...checked.media]){const id=C.uid();mapped.set(row.id,id);await audioTask('readwrite',store=>store.put({id,sessionId:row.sessionId,blob:row.blob}));}
 for(const s of checked.state.sessions)for(const note of [...s.voice,...(s.media||[])])note.id=mapped.get(note.id);
 const catalog=await autoStore.list().catch(()=>[]);
 checked.state.revision=Math.max(state.revision||0,checked.state.revision,...catalog.map(item=>item.revision))+1;C.validate(checked.state);
 if(localStorage.getItem(C.KEY)!==before)throw Error('Companion data changed in another window. Reload before restoring.');
 if(before)localStorage.setItem(C.KEY+'.previous',before);
 localStorage.setItem(C.KEY,JSON.stringify(checked.state));state=checked.state;loadError=null;
 scheduleAutoBackup();toast('Companion sessions, voice notes and attachments restored.');navigate('sessions');return true;
}
async function restoreFile(e){const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>100000000)throw Error('Backup is larger than 100 MB.');await restorePayload(JSON.parse(await file.text()));}catch(error){toast('Restore did not finish: '+error.message);}}
const autoStore=B.repository();let autoEnabled=true,autoTimer=null,autoQueue=Promise.resolve(),autoMessage='',autoBusy=false;
try{autoEnabled=localStorage.getItem(B.PREF)!=='off';}catch{autoEnabled=false;autoMessage='Auto backup preference could not be read.';}
function autoBackupControls(){return `<section class="auto-backup" aria-labelledby="autoBackupTitle"><div class="auto-backup-heading"><h3 id="autoBackupTitle">Auto backup</h3><button id="autoBackupToggle" type="button" role="switch" aria-label="Auto backup" aria-checked="${autoEnabled}" data-action="toggle-auto">${autoEnabled?'On':'Off'}</button></div><p class="hint">Keeps five recent recovery copies, including audio and attachments, on this device while Companion Play is open. Export a backup to keep a copy elsewhere.</p><p id="autoBackupStatus" class="hint" role="status">Checking saved copies…</p><details><summary>Restore an auto backup</summary><div id="autoBackupList"></div></details></section>`;}
async function refreshAutoBackups(){
 const list=$('autoBackupList'),status=$('autoBackupStatus');if(!list||!status)return;
 try{const copies=await autoStore.list();if(!list.isConnected)return;
  const last=copies[0];status.textContent=autoMessage||(autoBusy?'Saving recovery copy…':autoEnabled?(last?'Last backup: '+new Date(last.savedAt).toLocaleString():'Auto backup is on. Your first copy is being prepared.'):'Auto backup is off. Existing recovery copies stay saved.');
  list.innerHTML=copies.length?copies.map(item=>`<div class="auto-backup-row"><div><strong>${esc(new Date(item.savedAt).toLocaleString())}</strong><p class="hint">${item.sessions} sessions · ${item.audio} audio notes</p></div><button data-action="restore-auto" data-backup="${esc(item.id)}">Restore</button></div>`).join(''):'<p class="hint">No auto backups saved yet.</p>';
 }catch(e){if(status.isConnected)status.textContent='Auto backup unavailable: '+e.message+' You can still prepare a manual backup.';}
}
function captureAutoBackup(force=false){
 const job=async()=>{if((!autoEnabled&&!force)||loadError)return;autoBusy=true;refreshAutoBackups();try{const payload=await makeBackup();if(!autoEnabled&&!force)return;const saved=await autoStore.save(payload,{force});autoMessage='';return saved;}catch(e){autoMessage='Auto backup did not finish: '+e.message;throw e;}finally{autoBusy=false;refreshAutoBackups();}};
 const result=autoQueue.then(job);autoQueue=result.catch(()=>{});return result;
}
function scheduleAutoBackup(){if(!autoEnabled||loadError||autoTimer)return;autoTimer=setTimeout(()=>{autoTimer=null;captureAutoBackup().catch(e=>toast('Auto backup did not finish. Your session is still saved. '+e.message));},1500);}
async function toggleAutoBackup(){
 const next=!autoEnabled;try{localStorage.setItem(B.PREF,next?'on':'off');autoEnabled=next;autoMessage='';clearTimeout(autoTimer);autoTimer=null;const button=$('autoBackupToggle');button?.setAttribute('aria-checked',String(next));if(button)button.textContent=next?'On':'Off';if(next)await captureAutoBackup();else refreshAutoBackups();}catch(e){toast('Auto backup: '+e.message);refreshAutoBackups();}
}
async function restoreAutoBackup(button){button.disabled=true;try{const payload=await autoStore.get(button.dataset.backup);if(!payload)throw Error('That recovery copy is no longer available.');await restorePayload(payload);}catch(e){toast('Restore did not finish: '+e.message);}finally{button.disabled=false;refreshAutoBackups();}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&autoEnabled&&!loadError){clearTimeout(autoTimer);autoTimer=null;captureAutoBackup().catch(()=>{});}});
window.addEventListener('billiards:description-speech',e=>{if(e.detail==='error')toast('Device speech could not play. Check the voice installed on this device.');});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('beforeunload',e=>{if(recording||recordPending){e.preventDefault();e.returnValue='';}});
window.addEventListener('billiards:before-close',e=>{if(recording||recordPending){e.preventDefault();toast('Stop and save the voice note before leaving.');}});
document.addEventListener('click',e=>{if((recording||recordPending)&&e.target.closest('a')){e.preventDefault();toast('Stop and save the voice note before leaving.');}},true);
window.addEventListener('hashchange',route);
function route(){
 N.stop();const path=location.hash.slice(1)||'home',parts=path.split('/'),tool=C.toolRoute(path);
 view=parts[0];detailId=parts[1]||'';
 if(!['home','new','session','sessions','discoveries','detail','features','devices','settings',...W.views].includes(view))view='home';
 if(tool?.requiresSession&&!session())pendingTool=path;
 else if(tool?.view==='session'&&tool.stage!==undefined&&session()){
  if(tool.stage>0&&!session().agreed){pendingTool=path;if(session().stage!==0)update(s=>s.stage=0,false);}
  else {pendingTool='';if(session().stage!==tool.stage||(tool.practiceStep!==undefined&&session().practiceStep!==tool.practiceStep))update(s=>{s.stage=tool.stage;if(tool.practiceStep!==undefined)s.practiceStep=tool.practiceStep;},false);}
 }else if(!['new','sessions','session'].includes(view))pendingTool='';
 render();main.focus({preventScroll:true});window.scrollTo(0,0);
 if(tool?.requiresSession&&!session()){
  main.insertAdjacentHTML('afterbegin','<p class="toolkit-context">Choose or start a session, and we’ll bring you back to this tool.</p>');
 }else if(pendingTool&&view==='session'&&session()&&!session().agreed){
  main.insertAdjacentHTML('afterbegin','<p class="toolkit-context">Agree how you’d like to practice, then continue to your chosen tool.</p>');
 }else if(tool?.section){const target=$('tool-'+tool.section);if(target){for(let node=target;node&&node!==main;node=node.parentElement)if(node.tagName==='DETAILS')node.open=true;target.tabIndex=-1;target.classList.add('toolkit-target');target.focus({preventScroll:true});target.scrollIntoView({block:'center'});}}
}

N.mount(()=>{if(recording||recordPending){toast('Stop the voice note before narration.');return false;}W.stopVoice();return true;});
W.mount({state:()=>state,session,change,render,navigate,esc,heading,toast,audioTask,recording:()=>recording||recordPending});
route();scheduleAutoBackup();
})();
